scripts.script:
local table = {}


local hk;
hk = hookmetamethod(game, "__namecall", function(self, ...)
    local args = {...}
    local method = getnamecallmethod()

    if tostring(self) == "GetBrawlerInventory" or tostring(self) == "GetBrawlers" and method == "InvokeServer" then

        for i, v in pairs(game:GetService("ReplicatedStorage").RewardGUI.BrawlerCards:GetChildren()) do
            table[v.Name] = { [v.Name] = {} }
        end


        return table
    end

    return hk(self, unpack(args))
end)
